(function(){const t=240,n=160,o=289,i=4,c=8/6.283,r=10*c,s=8*c,e=4,f=[3,1,2];let l=0,u=0,a=1,M=0,C=0,d=-1,m=2;function q(){for(let i=0;i<4;i++){const i=Math.sqrt(r*u);if(i>=o){u=0,a=-a,M=(M+1)%3;continue}const s=i/c*a;h.setColor(f[M]).fillCircle(t+i*Math.cos(s)|0,n+i*Math.sin(s)|0,4),u++}}function v(){for(let o=0;o<4;o++){const o=83521-s*C;if(o<=0){C=0,d=-d,m=(m+1)%3;continue}const i=Math.sqrt(o),r=i/c*d;h.setColor(f[m]).fillCircle(t+i*Math.cos(r)|0,n+i*Math.sin(r)|0,4),C++}}return{id:"SNAKE",init:function(t){l=t,u=0,a=1,M=0,C=0,d=-1,m=2},draw:function(h){"ram";1!==l&&q(),0!==l&&v()},remove:function(){}}});